<script setup lang="ts">import{ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from '@/shared/components/WareState.vue';import{sessionStore}from'@/store/session';import{patrolPunishmentApi,type PatrolRecord,type Offender}from'../../api/patrol-punishment.api';const today=new Date().toISOString().slice(0,10);const date=ref(today),keyword=ref(''),type=ref(0),status=ref<number|''>(''),records=ref<PatrolRecord[]>([]),stats=ref({dailyCount:0,monthlyCount:0}),offenders=ref<Offender[]>([]),loading=ref(true),error=ref(''),form=ref(false),saving=ref(false),draft=ref({type:2,dutyUserId:0,dutyUserRole:'',dutyUserName:'',orderSn:'',date:today,zoneShelf:'',zone:'',shelf:'',reason:'',remark:'',price:'10'});const statusName=(v:number)=>({0:'待确认',1:'已确认',2:'已撤销'}[v]||'未知'),typeName=(v:number)=>v===1?'设箱型号错误':'配错货';async function load(){loading.value=true;try{[records.value,stats.value]=await Promise.all([patrolPunishmentApi.records({date:date.value,keyword:keyword.value,type:type.value,status:status.value}),patrolPunishmentApi.statistics(date.value)]);error.value=''}catch(e){error.value=e instanceof Error?e.message:'巡线处罚加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}async function openCreate(t:number){draft.value={type:t,dutyUserId:0,dutyUserRole:'',dutyUserName:'',orderSn:'',date:date.value,zoneShelf:'',zone:'',shelf:'',reason:'',remark:'',price:'10'};if(!offenders.value.length)offenders.value=await patrolPunishmentApi.offenders();form.value=true;uni.scanCode({success:r=>draft.value.orderSn=r.result,fail:()=>{}})}function pickOffender(i:number){const x=offenders.value[i];draft.value.dutyUserId=x.id;draft.value.dutyUserRole=x.role_code;draft.value.dutyUserName=x.name}async function submit(){if(saving.value)return;saving.value=true;try{await patrolPunishmentApi.create({...draft.value,price:Number(draft.value.price)});form.value=false;uni.showToast({title:'处罚已提交',icon:'success'});load()}catch(e){uni.showToast({title:e instanceof Error?e.message:'提交失败',icon:'none'})}finally{saving.value=false}}function revoke(x:PatrolRecord){uni.showModal({title:'撤销处罚',content:'确定撤销当前处罚吗？撤销后保留历史记录。',success:async r=>{if(!r.confirm)return;await patrolPunishmentApi.revoke(x.id);uni.showToast({title:'已撤销',icon:'success'});load()}})}onLoad(load);onPullDownRefresh(load);</script>
<template><view class="page"><view class="actions"><view @click="openCreate(2)"><image src="/static/icons/wms/fwms-scan-outline.svg"/><view><b>扫码配错货</b><text>配货环节处罚</text></view></view><view @click="openCreate(1)"><image src="/static/icons/wms/fwms-scan-outline.svg"/><view><b>扫码设箱错误</b><text>打包环节处罚</text></view></view></view><view class="stats"><view><text>当日处罚</text><b>{{stats.dailyCount}}<small>次</small></b></view><view><text>当月处罚</text><b>{{stats.monthlyCount}}<small>次</small></b></view></view><view class="filters"><input v-model="keyword" placeholder="被处罚人员" @confirm="load"/><picker mode="date" :value="date" @change="date=$event.detail.value;load()"><view>{{date}}⌄</view></picker><picker :range="['全部类型','设箱错误','配错货']" @change="type=Number($event.detail.value);load()"><view>{{type?typeName(type):'全部类型'}}⌄</view></picker><picker :range="['全部状态','待确认','已确认','已撤销']" @change="status=Number($event.detail.value)?Number($event.detail.value)-1:'';load()"><view>{{status===''?'全部状态':statusName(status)}}⌄</view></picker></view><WareState v-if="loading||error||!records.length" :type="loading ? 'loading' : error ? 'error' : 'empty'" :title="loading ? '正在加载' : error ? '加载失败' : '暂无巡线处罚'" :description="error" :action-label="error ? '重新加载' : undefined" @action="load"/><view v-else class="card" v-for="x in records" :key="x.id"><view class="card-head"><view><b>{{typeName(x.type)}}</b><text :class="`s${x.punish_status}`">{{statusName(x.punish_status)}}</text></view><strong>¥{{Number(x.punish_price).toFixed(2)}}</strong></view><view class="info"><text>被处罚人</text><b>{{x.duty_user_name}}</b><text>货架号</text><b>{{x.zone_shelf||'--'}}</b><text>处罚说明</text><b>{{x.punish_reason}}</b><text>处罚时间</text><b>{{x.create_time}}</b><text>处罚人</text><b>{{x.operator_name}}</b></view><button v-if="x.punish_status===0&&sessionStore.can('patrolPunishment.revoke')" @click="revoke(x)">撤销处罚</button></view><view v-if="form" class="mask" @click="form=false"><view class="drawer" @click.stop><view class="handle"></view><b>新增{{typeName(draft.type)}}处罚</b><label>被处罚人员*</label><picker :range="offenders.map(x=>`${x.name} · ${x.role_name}`)" @change="pickOffender(Number($event.detail.value))"><view class="input">{{draft.dutyUserName||'请选择人员'}}⌄</view></picker><label>扫码内容/关联单号</label><input v-model="draft.orderSn" class="input" placeholder="扫码后自动带入，也可手动填写"/><label>货架号*</label><input v-model="draft.zoneShelf" class="input" placeholder="例如 09-117-2"/><label>处罚金额*</label><input v-model="draft.price" class="input" type="digit" placeholder="1-10000元"/><label>处罚说明*</label><textarea v-model="draft.reason" placeholder="请填写现场问题和判断依据"/><label>备注</label><input v-model="draft.remark" class="input" placeholder="选填"/><view class="drawer-actions"><button @click="form=false">取消</button><button :disabled="saving" @click="submit">{{saving?'提交中…':'提交处罚'}}</button></view></view></view></view></template>
<style scoped>.page{min-height:100vh;padding:20rpx;background:var(--wms-background)}.actions{display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.actions>view{display:flex;min-height:94rpx;align-items:center;gap:13rpx;padding:15rpx;border-radius:14rpx;background:#fff}.actions image{width:40rpx;height:40rpx}.actions b,.actions text{display:block}.actions b{font-size:21rpx}.actions text{margin-top:4rpx;color:var(--wms-text-secondary);font-size:17rpx}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:12rpx}.stats>view{padding:18rpx;border-radius:14rpx;background:#fff}.stats text,.stats b{display:block}.stats text{color:var(--wms-text-secondary);font-size:19rpx}.stats b{margin-top:4rpx;color:var(--wms-danger);font-size:33rpx}.stats small{display:inline;margin-left:3rpx;font-size:17rpx}.filters{display:grid;grid-template-columns:1.2fr 1fr;gap:9rpx;margin:14rpx 0}.filters input,.filters picker view{box-sizing:border-box;height:58rpx;padding:0 11rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:18rpx;line-height:58rpx}.card{margin-bottom:12rpx;padding:20rpx;border-radius:14rpx;background:#fff}.card-head,.card-head>view{display:flex;align-items:center}.card-head{justify-content:space-between}.card-head>view{gap:9rpx}.card-head text{padding:3rpx 7rpx;border-radius:5rpx;background:#fff3d9;color:var(--wms-warning);font-size:17rpx}.card-head .s1{background:var(--wms-surface-soft);color:var(--wms-success)}.card-head .s2{background:#f0f2f2;color:var(--wms-text-secondary)}.card-head strong{color:var(--wms-danger);font-size:27rpx}.info{display:grid;grid-template-columns:130rpx 1fr;gap:11rpx;margin-top:16rpx;font-size:19rpx}.info text{color:var(--wms-text-secondary)}.info b{text-align:right}.card button{width:auto;margin:17rpx 0 0 auto;padding:0 18rpx;border:1rpx solid var(--wms-danger);border-radius:8rpx;background:#fff;color:var(--wms-danger);font-size:18rpx;line-height:48rpx}.mask{position:fixed;z-index:80;inset:0;display:flex;align-items:flex-end;background:#0007}.drawer{box-sizing:border-box;max-height:92vh;width:100%;padding:14rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));overflow-y:auto;border-radius:24rpx 24rpx 0 0;background:#fff}.handle{width:68rpx;height:7rpx;margin:0 auto 20rpx;border-radius:7rpx;background:var(--wms-border)}.drawer>b{font-size:27rpx}.drawer label{display:block;margin:17rpx 0 7rpx;font-size:20rpx}.input,.drawer textarea{box-sizing:border-box;width:100%;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:20rpx}.input{height:64rpx;padding:0 13rpx;line-height:64rpx}.drawer textarea{height:120rpx;padding:13rpx}.drawer-actions{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:22rpx}.drawer-actions button{margin:0;border-radius:8rpx;font-size:21rpx}.drawer-actions button:last-child{background:var(--wms-primary-700);color:#fff}</style>
